std::priority_queue<std::pair<double, int>, std::vector<std::pair<double, int>>, std::greater<std::pair<double, int>>> open_set;
std::unordered_map<int, double> g_score;
std::unordered_map<int, double> f_score;
std::unordered_map<int, int> came_from;
std::unordered_set<int> closed_set;

for (const auto& node : graph.get_nodes()) {
    g_score[node.id] = std::numeric_limits<double>::max();
    f_score[node.id] = std::numeric_limits<double>::max();
}

g_score[start_idx] = 0.0;
f_score[start_idx] = graph.heuristic(start_idx, end_idx);
open_set.emplace(f_score[start_idx], start_idx);

while (!open_set.empty()) {
    int current = open_set.top().second;
    open_set.pop();

    if (closed_set.find(current) != closed_set.end()) continue;
    closed_set.insert(current);

    if (current == end_idx) {
        std::vector<Node> path;
        while (current != start_idx) {
            path.push_back(graph.get_node(current));
            current = came_from[current];
        }
        path.push_back(graph.get_node(start_idx));
        std::reverse(path.begin(), path.end());
        return path;
    }

    for (const auto& neighbor : graph.get_neighbors(current)) {
        if (closed_set.find(neighbor.id) != closed_set.end()) continue;

        double tentative_g_score = g_score[current] + graph.edge_weight(current, neighbor.id);
        if (tentative_g_score < g_score[neighbor.id]) {
            came_from[neighbor.id] = current;
            g_score[neighbor.id] = tentative_g_score;
            f_score[neighbor.id] = g_score[neighbor.id] + graph.heuristic(neighbor.id, end_idx);
            open_set.emplace(f_score[neighbor.id], neighbor.id);
        }
    }
}

return std::vector<Node>();

